      if (Array.isArray(m)) { arr = true; m = { join_ref: m[0], ref: m[1], topic: m[2], event: m[3], payload: m[4] }; }
      const send = (o) => ws.send(JSON.stringify(arr ? [o.join_ref ?? null, o.ref ?? null, o.topic, o.event, o.payload] : o));
