      const expectSlots = bd.rows.filter(r => bd.to && r.day <= bd.to).map(r => r.day + "|" + r.role);
      const gotSlots = openFeed && openFeed.data && Array.isArray(openFeed.data.slots) ? openFeed.data.slots.map(s => s.day + "|" + s.role) : null;
