        if (k === "settings") { mine = { ...mine }; delete mine.importedAt; const sub = {}; Object.keys(mine).forEach(kk => { sub[kk] = theirs[kk]; }); if ("seedRevisions" in theirs) sub.seedRevisions = theirs.seedRevisions; theirs = sub; }
