        await settleB7();
        await b7.goto("about:blank");
        await b7.goto(BASE + linkHash(B7_OTHER, "b7-other-refresh"), { waitUntil: "domcontentloaded" });
        await b7.waitForSelector("[data-testid=link-conflict]", { timeout: 20000 });
